      SUBROUTINE PARCON(IPARM,VALUE)C---- ALLOCATE CONSTANT CELLCC---------------------------------------------------------------------      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'DATA2A.CIN'      INCLUDE 'DATUM.CIN'      INCLUDE 'RDWRDS.CIN'C---------------------------------------------------------------------      EQUIVALENCE     (FAKE,LAKE)C      IPARM = I + 1      NWORD = 2      NDESC = 1      LAKE = 30      DATUM(1) = FAKE      DATUM(2) = VALUE      CALL ELSTOR      RETURN      END